<template>
  <div class="setting-sidebar view-sidebar">
    <el-form ref="viewForm" :model="vrModel">
      <div class="setting-sidebar-item view-sidebar-screenshot">
        <div class="setting-sidebar-title">
          当前初始视角
          <el-tooltip class="item" effect="dark" content="打开场景时，默认展示的位置内容" placement="top">
            <i class="el-icon-warning"></i>
          </el-tooltip>
        </div>
        <div class="view-sidebar-screenshot-img">
          <el-image v-if="vrCentrePreviewImg" :src="vrCentrePreviewImg" fit="cover"></el-image>
        </div>
      </div>
      <div class="setting-sidebar-item">
        <div class="setting-sidebar-title">
          视角（FOV）范围设置
          <el-tooltip
            class="item"
            effect="dark"
            content="分为“最近”和“最远”，“最近”是指场景画面可放大到的最近距离(1)，“最远”是指场景画面可缩小到的最远距离(179)"
            placement="top"
          >
            <i class="el-icon-warning"></i>
          </el-tooltip>
        </div>
        <div class="view-sidebar-body">
          <el-form-item>
            <el-slider
              v-model="fovRange"
              :min="1"
              :max="179"
              range
              :marks="fovMarks"
              @input="onFovChange"
            ></el-slider>
          </el-form-item>
        </div>
      </div>
      <div class="setting-sidebar-item">
        <div class="setting-sidebar-title">
          水平视角限制
          <el-tooltip class="item" effect="dark" content="球体矫正水平视角" placement="top">
            <i class="el-icon-warning"></i>
          </el-tooltip>
        </div>
        <div class="view-sidebar-body">
          <el-form-item>
            <el-slider
              v-model="sphereCorrectionModel.pan"
              :min="-180"
              :max="180"
              :marks="sphereCorrectionMarks"
              @input="onSphereCorrectionChange('pan', $event)"
            ></el-slider>
          </el-form-item>
        </div>
      </div>
      <div class="setting-sidebar-item">
        <div class="setting-sidebar-title">
          旋转视角限制
          <el-tooltip class="item" effect="dark" content="球体矫正旋转视角" placement="top">
            <i class="el-icon-warning"></i>
          </el-tooltip>
        </div>
        <div class="view-sidebar-body">
          <el-form-item>
            <el-slider
              v-model="sphereCorrectionModel.roll"
              :min="-180"
              :max="180"
              :marks="sphereCorrectionMarks"
              @input="onSphereCorrectionChange('roll', $event)"
            ></el-slider>
          </el-form-item>
        </div>
      </div>
      <div class="setting-sidebar-item">
        <div class="setting-sidebar-title">
          垂直视角限制
          <el-tooltip class="item" effect="dark" content="球体矫正垂直视角" placement="top">
            <i class="el-icon-warning"></i>
          </el-tooltip>
        </div>
        <div class="view-sidebar-body">
          <el-form-item>
            <el-slider
              v-model="sphereCorrectionModel.tilt"
              :min="-180"
              :max="180"
              :marks="sphereCorrectionMarks"
              @input="onSphereCorrectionChange('tilt', $event)"
            ></el-slider>
          </el-form-item>
        </div>
      </div>
      <div class="setting-sidebar-item other-setting-sidebar-item">
        <div class="setting-sidebar-title">其它配置</div>
        <div class="view-sidebar-body">
          <el-form-item label="缩放级别">
            <el-input-number v-model="vrModel.defaultZoomLvl" :min="0" size="small"></el-input-number>
          </el-form-item>
          <el-form-item label="自旋速度">
            <el-input-number v-model="vrModel.autorotateSpeed" :min="0" :step="0.1" size="small"></el-input-number>
          </el-form-item>
          <el-form-item label="移动速度">
            <el-input-number v-model="vrModel.moveSpeed" :min="0.3" :step="0.1" size="small"></el-input-number>
          </el-form-item>
          <el-form-item label="缩放速度">
            <el-input-number v-model="vrModel.zoomSpeed" :min="1" :step="0.1" size="small"></el-input-number>
          </el-form-item>
        </div>
      </div>
      <div class="fix-setting-sidebar-item">
        <el-button type="primary" size="small" @click="saveVrOptions" :loading="saveLoading">应用到当前场景</el-button>
      </div>
    </el-form>
  </div>
</template>
<script>
export default {
  name: 'ViewSidebar',
  props: {
    vrOptions: Object
  },
  data() {
    return {
      vrModel: null,
      vrCentrePreviewImg: null,
      vrPosition: null,
      fovRange: [],
      sphereCorrectionMarks: {
        '-180': '-180',
        '-90': '-90',
        0: '0',
        90: '90',
        180: '180'
      },
      saveLoading: false
    }
  },
  created() {
    this.vrModel = this.vrOptions
    console.log('vrModel:', this.vrModel)
    this.sphereCorrectionModel = this.vrModel.sphereCorrection
    this.fovMarks = {
      1: '1',
      179: '179'
    }
    if (this.vrModel) {
      this.fovRange = [this.vrModel.minFov, this.vrModel.maxFov]
    }
    this.$bus.$on('setVRCenterAngle', result => {
      // console.log('result:', result)
      this.vrCentrePreviewImg = result.img
      if (result.zoomLevel > this.vrModel.maxFov) {
        this.vrModel.maxFov = parseInt(result.zoomLevel)
        this.$set(this.fovRange, 1, this.vrModel.maxFov)
      }
      if (result.zoomLevel < this.vrModel.minFov) {
        this.vrModel.minFov = parseInt(result.zoomLevel)
        this.$set(this.fovRange, 0, this.vrModel.minFov)
      }
    })
    // this.$bus.$on('setVRCenterAngleImg', result => {
    //   this.vrCentrePreviewImg = result.img
    // })
  },
  methods: {
    setFovChange(value) {
      this.fovRange = value
    },
    onFovChange(value) {
      this.$emit('onFovChange', value)
    },
    onSphereCorrectionChange(type, value) {
      this.$emit('onSphereCorrectionChange', type, value)
    },
    saveVrOptions() {
      if (this.fovRange[0] > this.fovRange[1]) {
        this.$message.error('最大视角maxFov不能小于最低视角minFov')
        return false
      }
      this.saveLoading = true
      this.$emit('onSaveVrOptions')
      // this.saveLoading = false
    }
  }
}
</script>
